#!/usr/bin/env python3
"""S38 audit (independent referee): independent re-check of THM-4661 statement 5 (no graph on n <= 21 vertices
satisfies the necessary conditions (N1)-(N4) of a vertex-minimal failed six-colour exterior).

Independent of six_colour_exterior_twenty_sat_20261016.py in every component:
  * attachment patterns: pair graphs on the root's d neighbours generated by brute force over edge subsets with the
    degree filters and deduplicated by an exact canonical form (minimum edge bitmask over all d! relabellings), not
    taken from the networkx atlas; singles enumerated as multisets up to the pair graph's automorphism group computed
    by brute force; the pattern counts are compared with the S38 counts (1, 7, 38 at n = 19, 20, 21; 135 + 2 at 22);
  * SAT encoding: cardinality constraints with sorting networks (EncType.cardnetwrk / sortnetwrk) instead of
    sequential counters and totalizers; the Gallai count as a single cardinality constraint over repeated literals
    encoded by a sorting network; solver Glucose 4 instead of CaDiCaL;
  * the same necessary conditions: (N1) triangle-free, codegree <= 2; (N2) lists 6 - t(v), deg >= 6 - t(v), high iff
    deg >= 7 - t(v), low vertices have deg = 6 - t(v); (N3) no 4-cycle among low vertices and
    4|E(low)| <= 5(#low - 1) when some vertex is low; (N4) the root z is high, of maximum degree d among high
    vertices, so all degrees <= d (low vertices have degree <= 6 <= d).
Output: audit_exterior_sat_independent.out and .json.  Usage: python audit_exterior_sat_independent.py 19 20 21 [22]
(for n = 22 only the pattern counts are computed).
"""
import itertools, json, math, os, sys, time
from pysat.formula import IDPool
from pysat.card import CardEnc, EncType
from pysat.solvers import Solver

HERE = os.path.dirname(os.path.abspath(__file__))
OUTJ = os.path.join(HERE, 'audit_exterior_sat_independent.json')


def log(*a):
    print(*a, flush=True)


def canon(d, edges):
    """Exact canonical form of a graph on range(d): minimal sorted edge tuple over all relabellings."""
    best = None
    for perm in itertools.permutations(range(d)):
        t = tuple(sorted(tuple(sorted((perm[a], perm[b]))) for a, b in edges))
        if best is None or t < best:
            best = t
    return best


def automorphisms(d, edges):
    E = {tuple(sorted(e)) for e in edges}
    auts = []
    for perm in itertools.permutations(range(d)):
        if all(tuple(sorted((perm[a], perm[b]))) in E for a, b in E):
            auts.append(perm)
    return auts


_PG_CACHE = {}


def pair_graphs(d, pmax, degmax):
    key = (d, degmax)
    if key not in _PG_CACHE:
        _PG_CACHE[key] = _pair_graphs(d, d * (d - 1) // 2, degmax)
    return [g for g in _PG_CACHE[key] if len(g) <= pmax]


def _pair_graphs(d, pmax, degmax):
    allpairs = list(itertools.combinations(range(d), 2))
    seen = {}
    for p in range(0, pmax + 1):
        for es in itertools.combinations(allpairs, p):
            deg = [0] * d
            for a, b in es:
                deg[a] += 1; deg[b] += 1
            if max(deg) > degmax:
                continue
            c = canon(d, es) if d <= 6 else None
            if c is None:
                continue
            if c not in seen:
                seen[c] = list(c)
    return list(seen.values())


def patterns(n, d):
    out = []
    mmax = n - 1 - d
    graphs = pair_graphs(d, mmax, d - 1)
    for g in graphs:
        p = len(g)
        pdeg = [0] * d
        for a, b in g:
            pdeg[a] += 1; pdeg[b] += 1
        auts = automorphisms(d, g)
        for m in range(p, mmax + 1):
            s = m - p
            seen = set()
            for S in itertools.combinations_with_replacement(range(d), s):
                att = pdeg[:]
                for x in S:
                    att[x] += 1
                if any(not (4 <= a <= d - 1) for a in att):
                    continue
                key = min(tuple(sorted(perm[x] for x in S)) for perm in auts)
                if key in seen:
                    continue
                seen.add(key)
                out.append((m, g, list(key)))
    return out


def solve(n, d, m, pairs, singles):
    z = 0
    U = list(range(1, d + 1))
    W = list(range(d + 1, d + 1 + m))
    F = list(range(d + 1 + m, n))
    V = list(range(n))
    pool = IDPool()
    fixed = {}
    att = {}
    for i, (a, b) in enumerate(pairs):
        att[W[i]] = {U[a], U[b]}
    for k, s in enumerate(singles):
        att[W[len(pairs) + k]] = {U[s]}
    for v in V:
        if v != z:
            fixed[(z, v)] = v in U
    for a, b in itertools.combinations(U, 2):
        fixed[(a, b)] = False
    for u in U:
        for w in W:
            fixed[(u, w)] = u in att[w]
        for f in F:
            fixed[(u, f)] = False

    def L(a, b):
        a, b = min(a, b), max(a, b)
        if (a, b) in fixed:
            return fixed[(a, b)]
        return pool.id(('x', a, b))

    cls = []
    # (N1) triangles
    for a, b, c in itertools.combinations(V, 3):
        ls = [L(a, b), L(b, c), L(a, c)]
        if False in ls:
            continue
        cl = [-l for l in ls if l is not True]
        if not cl:
            return 'UNSAT(fixed triangle)'
        cls.append(cl)
    # (N1) codegree <= 2
    for a, b in itertools.combinations(V, 2):
        forced, terms = 0, []
        for k in V:
            if k in (a, b):
                continue
            la, lb = L(a, k), L(b, k)
            if la is False or lb is False:
                continue
            if la is True and lb is True:
                forced += 1
            elif la is True or lb is True:
                terms.append(lb if la is True else la)
            else:
                y = pool.id(('both', a, b, k))
                cls += [[-y, la], [-y, lb], [y, -la, -lb]]
                terms.append(y)
        if forced > 2:
            return 'UNSAT(fixed codegree)'
        if len(terms) > 2 - forced:
            cls += CardEnc.atmost(terms, bound=2 - forced, vpool=pool, encoding=EncType.sortnetwrk).clauses
    # (N2) degrees
    t = {v: pool.id(('t', v)) for v in V}
    h = {v: pool.id(('h', v)) for v in V}
    for v in V:
        inc = [L(v, u) for u in V if u != v]
        fc = sum(1 for l in inc if l is True)
        vs = [l for l in inc if l is not True and l is not False]

        def cond(kind, k, guard):          # guard -> (deg >= k) or (deg <= k); guard is a list of literals (conjunction)
            need = k - fc
            if kind == 'ge':
                if need <= 0:
                    return
                if need > len(vs):
                    cls.append([-g for g in guard]); return
                enc = CardEnc.atleast(vs, bound=need, vpool=pool, encoding=EncType.cardnetwrk)
            else:
                if need < 0:
                    cls.append([-g for g in guard]); return
                if need >= len(vs):
                    return
                enc = CardEnc.atmost(vs, bound=need, vpool=pool, encoding=EncType.cardnetwrk)
            for c in enc.clauses:
                cls.append(c + [-g for g in guard])

        cond('ge', 5, [])
        cond('le', d, [])
        nt = pool.id(('nt', v)); cls += [[nt, t[v]], [-nt, -t[v]]]          # nt <-> not t
        nh = pool.id(('nh', v)); cls += [[nh, h[v]], [-nh, -h[v]]]
        cond('ge', 6, [nt])                       # list 6 -> deg >= 6
        cond('ge', 7, [h[v], nt])                 # high with list 6 -> deg >= 7
        cond('ge', 6, [h[v], t[v]])               # high with list 5 -> deg >= 6
        cond('le', 5, [nh, t[v]])                 # low with list 5 -> deg = 5
        cond('le', 6, [nh, nt])                   # low with list 6 -> deg = 6
    cls.append([h[z]])
    # (N3a) no 4-cycle among low vertices
    for a, b, c, e in itertools.combinations(V, 4):
        for (p, q, r, s) in ((a, b, c, e), (a, b, e, c), (a, c, b, e)):
            ls = [L(p, q), L(q, r), L(r, s), L(s, p)]
            if False in ls:
                continue
            cls.append([-l for l in ls if l is not True] + [h[a], h[b], h[c], h[e]])
    # (N3b) Gallai count: 4 |E(low)| + 5 #high + 5 [some low] <= 5 n
    reps = []
    for a, b in itertools.combinations(V, 2):
        l = L(a, b)
        if l is False:
            continue
        y = pool.id(('lowedge', a, b))
        base = [-y, -h[a]], [-y, -h[b]]
        cls += list(base)
        if l is True:
            cls.append([y, h[a], h[b]])
        else:
            cls += [[-y, l], [y, -l, h[a], h[b]]]
        reps += [y] * 4
    sl = pool.id(('somelow',))
    cls.append([-sl] + [-h[v] for v in V])
    cls += [[sl, h[v]] for v in V]
    reps += [h[v] for v in V for _ in range(5)] + [sl] * 5
    cls += CardEnc.atmost(reps, bound=5 * n, vpool=pool, encoding=EncType.sortnetwrk).clauses
    with Solver(name='glucose4', bootstrap_with=cls) as S:
        return 'SAT' if S.solve() else 'UNSAT'


if __name__ == '__main__':
    out = {}
    S38_counts = {19: 1, 20: 7, 21: 38, 22: 135}
    for n in [int(a) for a in sys.argv[1:]]:
        D = (n - 1) // 3
        t0 = time.time()
        res = []
        for d in range(6, min(D, 6) + 1):
            pats = patterns(n, d)
            log(f'n = {n}, root degree {d}: {len(pats)} patterns (S38: {S38_counts.get(n)})')
            if n >= 22:
                res.append(dict(d=d, patterns=len(pats)))
                continue
            verdicts = []
            for (m, g, S) in pats:
                v = solve(n, d, m, g, S)
                verdicts.append(v)
                if v != 'UNSAT':
                    log(f'   pattern m={m} pairs={g} singles={S}: {v}')
            res.append(dict(d=d, patterns=len(pats), verdicts=sorted(set(verdicts)), unsat=verdicts.count('UNSAT')))
            log(f'n = {n}: verdicts {sorted(set(verdicts))} ({verdicts.count("UNSAT")} UNSAT of {len(pats)}), '
                f'{time.time()-t0:.1f}s')
        out[n] = res
    json.dump(out, open(OUTJ, 'w'), indent=1)
    log('wrote', OUTJ)
